def write_jsonl(filename, data):
    path = os.path.join(OUTPUT_DIR, filename)
    with open(path, 'w') as f:
        for item in data:
            f.write(json.dumps(item) + '\n')
    print(f'  {filename}: {len(data)} examples')
    return len(data)

print(f'Generating training data in {OUTPUT_DIR}')
total = 0
total += write_jsonl('capability_data.jsonl', capability[:200])
total += write_jsonl('safety_data.jsonl', safety[:200])
total += write_jsonl('mixed_data.jsonl', mixed[:100])
total += write_jsonl('test_data.jsonl', test[:50])

print(f'Total: {total} examples')
print('Validating...')

# Validate
for fname in ['capability_data.jsonl', 'safety_data.jsonl', 'mixed_data.jsonl', 'test_data.jsonl']:
    path = os.path.join(OUTPUT_DIR, fname)
    with open(path) as f:
        lines = f.readlines()
        for i, line in enumerate(lines):
            try:
                obj = json.loads(line)
                assert 'messages' in obj
                assert len(obj['messages']) == 2
                assert obj['messages'][0]['role'] == 'user'
                assert obj['messages'][1]['role'] == 'assistant'
            except Exception as e:
                print(f'  ERROR in {fname} line {i+1}: {e}')
                raise
    print(f'  {fname}: VALID')

print('Done.')
